CREATE OR REPLACE FUNCTION public.criar_pedido_personalizado_lebebe_exclusive(p_usuario_id uuid, p_idempotency_key uuid, p_fornecedor_id uuid, p_unidade_id uuid, p_consultora text, p_cliente text, p_telefone_normalizado text, p_numero_lancamento text, p_itens jsonb)
 RETURNS TABLE(pedido_id uuid, version integer, reutilizado boolean, itens jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_pedido public.pedidos_personalizados_pedidos%rowtype;
  v_item jsonb;
  v_catalogo record;
  v_item_id uuid;
  v_total_itens integer;
  v_itens_retorno jsonb := '[]'::jsonb;
begin
  if p_usuario_id is null or not exists (
    select 1 from public.usuarios_permitidos where id = p_usuario_id and ativo = true
  ) then raise exception 'USUARIO_INVALIDO' using errcode = '42501'; end if;
  if p_idempotency_key is null then
    raise exception 'IDEMPOTENCY_KEY_INVALIDA' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_usuario_id::text || ':' || p_idempotency_key::text, 0)
  );

  select * into v_pedido
  from public.pedidos_personalizados_pedidos
  where created_by = p_usuario_id and idempotency_key = p_idempotency_key;

  if found then
    if v_pedido.fornecedor_id <> p_fornecedor_id then
      raise exception 'IDEMPOTENCY_KEY_CONFLITO' using errcode = '23505';
    end if;
    return query
    select v_pedido.id, v_pedido.version, true,
      coalesce((
        select jsonb_agg(jsonb_build_object('id', item.id, 'ordem', item.ordem) order by item.ordem)
        from public.pedidos_personalizados_lebebe_exclusive_itens as item
        where item.pedido_id = v_pedido.id
      ), '[]'::jsonb);
    return;
  end if;

  if not exists (
    select 1 from public.pedidos_personalizados_fornecedores
    where id = p_fornecedor_id and chave = 'lebebe_exclusive' and disponivel = true
  ) then raise exception 'FORNECEDOR_INDISPONIVEL' using errcode = '23514'; end if;
  if not exists (
    select 1 from public.app_unidades
    where id = p_unidade_id and ativo = true
      and chave in ('bigorrilho', 'portao', 'marechal', 'feira')
  ) then raise exception 'UNIDADE_NAO_PERMITIDA' using errcode = '22023'; end if;
  if p_consultora is null or char_length(btrim(p_consultora)) not between 2 and 20 then
    raise exception 'CONSULTORA_INVALIDA' using errcode = '22023';
  end if;
  if p_cliente is null or char_length(btrim(p_cliente)) not between 1 and 40 then
    raise exception 'CLIENTE_INVALIDO' using errcode = '22023';
  end if;
  if p_telefone_normalizado is null
     or p_telefone_normalizado !~ '^[0-9]{10,11}$'
     or left(p_telefone_normalizado, 2) = '00'
  then raise exception 'TELEFONE_INVALIDO' using errcode = '22023'; end if;
  if p_numero_lancamento is not null and p_numero_lancamento !~ '^[0-9]{1,6}$' then
    raise exception 'NUMERO_LANCAMENTO_INVALIDO' using errcode = '22023';
  end if;
  if p_itens is null or jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) < 1 then
    raise exception 'ITENS_OBRIGATORIOS' using errcode = '22023';
  end if;

  v_total_itens := jsonb_array_length(p_itens);
  if exists (
    select 1 from jsonb_array_elements(p_itens) as item(value)
    where jsonb_typeof(item.value) <> 'object'
       or item.value->>'produto_id' !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
       or item.value->>'ordem' !~ '^[0-9]+$'
       or (item.value->>'ordem')::integer not between 1 and v_total_itens
       or item.value->>'quantidade' !~ '^[0-9]+$'
       or (item.value->>'quantidade')::integer < 1
       or (item.value->>'nome_ou_letra' is not null and (
         btrim(item.value->>'nome_ou_letra') = ''
         or char_length(btrim(item.value->>'nome_ou_letra')) > 200
       ))
  ) or exists (
    select 1 from jsonb_array_elements(p_itens) as item(value)
    group by item.value->>'ordem' having count(*) > 1
  ) or exists (
    select 1 from jsonb_array_elements(p_itens) as item(value)
    group by item.value->>'produto_id' having count(*) > 1
  ) then raise exception 'ITEM_PEDIDO_INVALIDO' using errcode = '22023'; end if;

  insert into public.pedidos_personalizados_pedidos (
    fornecedor_id, unidade_id, consultora, cliente, telefone_normalizado,
    numero_lancamento, idempotency_key, created_by, updated_by
  ) values (
    p_fornecedor_id, p_unidade_id, btrim(p_consultora), btrim(p_cliente),
    p_telefone_normalizado, p_numero_lancamento, p_idempotency_key,
    p_usuario_id, p_usuario_id
  ) returning * into v_pedido;

  for v_item in
    select item.value from jsonb_array_elements(p_itens) as item(value)
    order by (item.value->>'ordem')::integer
  loop
    select produto.id, produto.descricao, catalogo.colecao, catalogo.referencia,
           catalogo.preco_unitario, catalogo.custo_unitario
      into v_catalogo
    from public.pedidos_personalizados_produtos as produto
    join public.pedidos_personalizados_lebebe_exclusive_catalogo as catalogo
      on catalogo.produto_id = produto.id
    where produto.id = (v_item->>'produto_id')::uuid
      and produto.fornecedor_id = p_fornecedor_id
      and produto.ativo = true;
    if not found then raise exception 'PRODUTO_FORNECEDOR_INVALIDO' using errcode = '23514'; end if;

    insert into public.pedidos_personalizados_lebebe_exclusive_itens (
      pedido_id, produto_id, ordem, quantidade, nome_ou_letra,
      colecao_snapshot, descricao_snapshot, referencia_snapshot,
      preco_unitario_snapshot, custo_unitario_snapshot, created_by, updated_by
    ) values (
      v_pedido.id, v_catalogo.id, (v_item->>'ordem')::integer,
      (v_item->>'quantidade')::integer, nullif(btrim(v_item->>'nome_ou_letra'), ''),
      v_catalogo.colecao, v_catalogo.descricao, v_catalogo.referencia,
      v_catalogo.preco_unitario, v_catalogo.custo_unitario,
      p_usuario_id, p_usuario_id
    ) returning id into v_item_id;

    v_itens_retorno := v_itens_retorno || jsonb_build_array(
      jsonb_build_object('id', v_item_id, 'ordem', (v_item->>'ordem')::integer)
    );
  end loop;

  return query select v_pedido.id, v_pedido.version, false, v_itens_retorno;
end;
$function$

CREATE OR REPLACE FUNCTION public.criar_pedido_personalizado_moriah(p_usuario_id uuid, p_idempotency_key uuid, p_fornecedor_id uuid, p_unidade_id uuid, p_consultora text, p_cliente text, p_tapetes jsonb, p_numero_lancamento text DEFAULT NULL::text, p_data_entrega date DEFAULT NULL::date, p_data_pedido_fornecedor date DEFAULT NULL::date, p_numero_pedido_compra text DEFAULT NULL::text, p_comprador text DEFAULT NULL::text)
 RETURNS TABLE(pedido_id uuid, version integer, reutilizado boolean, tapetes jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_pedido public.pedidos_personalizados_pedidos%ROWTYPE;
  v_tapete jsonb;
  v_cor jsonb;
  v_tapete_id uuid;
  v_produto_id uuid;
  v_cor_id uuid;
  v_total_tapetes integer;
  v_total_cores integer;
  v_tapetes_retorno jsonb := '[]'::jsonb;
BEGIN
  IF p_usuario_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.usuarios_permitidos
    WHERE id = p_usuario_id
      AND ativo = true
  ) THEN
    RAISE EXCEPTION 'USUARIO_INVALIDO' USING ERRCODE = '42501';
  END IF;

  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'IDEMPOTENCY_KEY_INVALIDA' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_usuario_id::text || ':' || p_idempotency_key::text, 0)
  );

  SELECT *
    INTO v_pedido
  FROM public.pedidos_personalizados_pedidos
  WHERE created_by = p_usuario_id
    AND idempotency_key = p_idempotency_key;

  IF FOUND THEN
    RETURN QUERY
    SELECT
      v_pedido.id,
      v_pedido.version,
      true,
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object('id', t.id, 'ordem', t.ordem)
            ORDER BY t.ordem
          )
          FROM public.pedidos_personalizados_moriah_tapetes AS t
          WHERE t.pedido_id = v_pedido.id
        ),
        '[]'::jsonb
      );
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pedidos_personalizados_fornecedores
    WHERE id = p_fornecedor_id
      AND disponivel = true
  ) THEN
    RAISE EXCEPTION 'FORNECEDOR_INDISPONIVEL' USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pedidos_personalizados_fornecedores
    WHERE id = p_fornecedor_id
      AND chave = 'moriah_tapetes'
  ) THEN
    RAISE EXCEPTION 'FORNECEDOR_NAO_SUPORTADO' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.app_unidades
    WHERE id = p_unidade_id
      AND ativo = true
      AND chave IN ('bigorrilho', 'portao', 'marechal', 'feira')
  ) THEN
    RAISE EXCEPTION 'UNIDADE_NAO_PERMITIDA' USING ERRCODE = '22023';
  END IF;

  IF p_tapetes IS NULL OR jsonb_typeof(p_tapetes) <> 'array' THEN
    RAISE EXCEPTION 'LIMITE_TAPETES' USING ERRCODE = '22023';
  END IF;

  v_total_tapetes := jsonb_array_length(p_tapetes);
  IF v_total_tapetes NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'LIMITE_TAPETES' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_tapetes) AS item(value)
    WHERE item.value->>'ordem' IS NULL
       OR item.value->>'ordem' !~ '^[0-9]+$'
  ) OR (
    SELECT count(*)
    FROM (
      SELECT item.value->>'ordem'
      FROM jsonb_array_elements(p_tapetes) AS item(value)
      GROUP BY item.value->>'ordem'
      HAVING count(*) > 1
    ) AS duplicadas
  ) > 0 THEN
    RAISE EXCEPTION 'ORDEM_TAPETE_DUPLICADA' USING ERRCODE = '22023';
  END IF;

  FOR v_tapete IN
    SELECT item.value
    FROM jsonb_array_elements(p_tapetes) AS item(value)
  LOOP
    IF jsonb_typeof(v_tapete) <> 'object'
       OR (v_tapete->>'ordem')::integer NOT BETWEEN 1 AND 10
       OR v_tapete->>'formato' NOT IN ('REDONDO', 'RETANGULAR', 'ORGANICO')
       OR v_tapete->>'tipo' NOT IN ('CATALOGO', 'PERSONALIZADO')
       OR v_tapete->>'dimensao_1_cm' IS NULL
       OR v_tapete->>'dimensao_1_cm' !~ '^[0-9]+$'
       OR (v_tapete->>'dimensao_1_cm')::integer NOT BETWEEN 10 AND 1500
       OR v_tapete->>'area_cobrada_centesimos_m2' IS NULL
       OR v_tapete->>'area_cobrada_centesimos_m2' !~ '^[0-9]+$'
       OR (v_tapete->>'area_cobrada_centesimos_m2')::integer NOT BETWEEN 1 AND 22500
       OR (v_tapete->>'produto_id') IS NULL
       OR (v_tapete->>'produto_id') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
       OR (
         v_tapete->>'formato' = 'REDONDO'
         AND v_tapete->>'dimensao_2_cm' IS NOT NULL
       )
       OR (
         v_tapete->>'formato' IN ('RETANGULAR', 'ORGANICO')
         AND (
           v_tapete->>'dimensao_2_cm' IS NULL
           OR v_tapete->>'dimensao_2_cm' !~ '^[0-9]+$'
           OR (v_tapete->>'dimensao_2_cm')::integer NOT BETWEEN 10 AND 1500
         )
       )
       OR (
         v_tapete->>'nome_colecao_catalogo' IS NOT NULL
         AND char_length(btrim(v_tapete->>'nome_colecao_catalogo')) NOT BETWEEN 1 AND 80
       )
       OR (
         v_tapete->>'referencia_catalogo' IS NOT NULL
         AND v_tapete->>'referencia_catalogo' !~ '^[A-Za-z0-9-]{1,40}$'
       )
       OR (
         v_tapete->>'observacoes' IS NOT NULL
         AND char_length(v_tapete->>'observacoes') > 500
       )
       OR (
         v_tapete->>'tipo' = 'CATALOGO'
         AND (
           v_tapete->>'nome_colecao_catalogo' IS NULL
           OR btrim(v_tapete->>'nome_colecao_catalogo') = ''
           OR v_tapete->>'referencia_catalogo' IS NULL
           OR btrim(v_tapete->>'referencia_catalogo') = ''
         )
       ) THEN
      RAISE EXCEPTION 'TAPETE_INVALIDO' USING ERRCODE = '22023';
    END IF;

    v_produto_id := (v_tapete->>'produto_id')::uuid;
    IF NOT EXISTS (
      SELECT 1
      FROM public.pedidos_personalizados_produtos
      WHERE id = v_produto_id
        AND fornecedor_id = p_fornecedor_id
        AND ativo = true
    ) THEN
      RAISE EXCEPTION 'PRODUTO_FORNECEDOR_INVALIDO' USING ERRCODE = '23514';
    END IF;

    IF v_tapete ? 'cores' AND jsonb_typeof(v_tapete->'cores') <> 'array' THEN
      RAISE EXCEPTION 'LIMITE_CORES' USING ERRCODE = '22023';
    END IF;

    v_total_cores := jsonb_array_length(COALESCE(v_tapete->'cores', '[]'::jsonb));
    IF v_total_cores > 6 THEN
      RAISE EXCEPTION 'LIMITE_CORES' USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_tapete->'cores', '[]'::jsonb)) AS cor(value)
      WHERE cor.value->>'ordem' IS NULL
         OR cor.value->>'ordem' !~ '^[0-9]+$'
         OR (cor.value->>'ordem')::integer NOT BETWEEN 1 AND 6
         OR cor.value->>'cor_id' IS NULL
         OR cor.value->>'cor_id' !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    ) OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_tapete->'cores', '[]'::jsonb)) AS cor(value)
      GROUP BY cor.value->>'ordem'
      HAVING count(*) > 1
    ) THEN
      RAISE EXCEPTION 'ORDEM_COR_DUPLICADA' USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(v_tapete->'cores', '[]'::jsonb)) AS cor(value)
      GROUP BY cor.value->>'cor_id'
      HAVING count(*) > 1
    ) THEN
      RAISE EXCEPTION 'COR_DUPLICADA' USING ERRCODE = '22023';
    END IF;

    FOR v_cor IN
      SELECT cor.value
      FROM jsonb_array_elements(COALESCE(v_tapete->'cores', '[]'::jsonb)) AS cor(value)
    LOOP
      v_cor_id := (v_cor->>'cor_id')::uuid;
      IF NOT EXISTS (
        SELECT 1
        FROM public.pedidos_personalizados_cores
        WHERE id = v_cor_id
          AND fornecedor_id = p_fornecedor_id
          AND ativo = true
      ) THEN
        RAISE EXCEPTION 'COR_FORNECEDOR_INVALIDA' USING ERRCODE = '23514';
      END IF;
    END LOOP;
  END LOOP;

  INSERT INTO public.pedidos_personalizados_pedidos (
    fornecedor_id,
    unidade_id,
    consultora,
    cliente,
    numero_lancamento,
    data_entrega,
    data_pedido_fornecedor,
    numero_pedido_compra,
    comprador,
    idempotency_key,
    created_by,
    updated_by
  ) VALUES (
    p_fornecedor_id,
    p_unidade_id,
    p_consultora,
    p_cliente,
    p_numero_lancamento,
    p_data_entrega,
    p_data_pedido_fornecedor,
    p_numero_pedido_compra,
    p_comprador,
    p_idempotency_key,
    p_usuario_id,
    p_usuario_id
  )
  RETURNING * INTO v_pedido;

  FOR v_tapete IN
    SELECT item.value
    FROM jsonb_array_elements(p_tapetes) AS item(value)
    ORDER BY (item.value->>'ordem')::integer
  LOOP
    v_tapete_id := gen_random_uuid();
    v_produto_id := (v_tapete->>'produto_id')::uuid;

    INSERT INTO public.pedidos_personalizados_moriah_tapetes (
      id,
      pedido_id,
      ordem,
      formato,
      tipo,
      dimensao_1_cm,
      dimensao_2_cm,
      area_cobrada_centesimos_m2,
      produto_id,
      nome_colecao_catalogo,
      referencia_catalogo,
      observacoes,
      created_by,
      updated_by
    ) VALUES (
      v_tapete_id,
      v_pedido.id,
      (v_tapete->>'ordem')::integer,
      v_tapete->>'formato',
      v_tapete->>'tipo',
      (v_tapete->>'dimensao_1_cm')::integer,
      NULLIF(v_tapete->>'dimensao_2_cm', '')::integer,
      (v_tapete->>'area_cobrada_centesimos_m2')::integer,
      v_produto_id,
      NULLIF(v_tapete->>'nome_colecao_catalogo', ''),
      NULLIF(v_tapete->>'referencia_catalogo', ''),
      v_tapete->>'observacoes',
      p_usuario_id,
      p_usuario_id
    );

    IF v_tapete->>'tipo' <> 'CATALOGO' THEN
      FOR v_cor IN
        SELECT cor.value
        FROM jsonb_array_elements(COALESCE(v_tapete->'cores', '[]'::jsonb)) AS cor(value)
        ORDER BY (cor.value->>'ordem')::integer
      LOOP
        INSERT INTO public.pedidos_personalizados_tapete_cores (
          tapete_id,
          cor_id,
          ordem
        ) VALUES (
          v_tapete_id,
          (v_cor->>'cor_id')::uuid,
          (v_cor->>'ordem')::integer
        );
      END LOOP;
    END IF;

    v_tapetes_retorno := v_tapetes_retorno || jsonb_build_array(
      jsonb_build_object(
        'id', v_tapete_id,
        'ordem', (v_tapete->>'ordem')::integer
      )
    );
  END LOOP;

  RETURN QUERY
  SELECT v_pedido.id, v_pedido.version, false, v_tapetes_retorno;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_own_record(record_email text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    user_email TEXT;
BEGIN
    user_email := auth.jwt()->>'email';
    
    IF user_email IS NULL THEN
        RETURN FALSE;
    END IF;
    
    RETURN LOWER(user_email) = LOWER(record_email);
END;
$function$

CREATE OR REPLACE FUNCTION public.is_superadmin()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    user_email TEXT;
    is_admin BOOLEAN;
BEGIN
    -- Pega o email do JWT do usuário autenticado
    user_email := auth.jwt()->>'email';
    
    IF user_email IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Verifica se é superadmin (SECURITY DEFINER bypassa RLS)
    SELECT EXISTS (
        SELECT 1 FROM usuarios_permitidos
        WHERE LOWER(email) = LOWER(user_email)
        AND role = 'superadmin'
        AND ativo = true
    ) INTO is_admin;
    
    RETURN COALESCE(is_admin, FALSE);
END;
$function$

CREATE OR REPLACE FUNCTION public.pedidos_personalizados_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.transicionar_pedido_personalizado(p_pedido_id uuid, p_expected_version integer, p_usuario_id uuid, p_status_destino text, p_numero_lancamento text DEFAULT NULL::text, p_numero_pedido_compra text DEFAULT NULL::text, p_data_pedido_fornecedor date DEFAULT NULL::date, p_comprador text DEFAULT NULL::text, p_data_entrega date DEFAULT NULL::date, p_justificativa text DEFAULT NULL::text)
 RETURNS TABLE(evento_id uuid, status text, version integer)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_p public.pedidos_personalizados_pedidos%rowtype; v_f text;
  v_i public.pedidos_personalizados_lebebe_exclusive_sgi%rowtype;
  v_lancamento text; v_evento uuid:=gen_random_uuid(); v_version integer;
  v_numero_pedido_compra text; v_data_pedido_fornecedor date; v_comprador text;
  v_data_entrega date; v_data_recebimento date; v_justificativa text; v_preenche_dados_compra boolean;
begin
  if p_usuario_id is null or not exists(select 1 from public.usuarios_permitidos u where u.id=p_usuario_id and u.ativo) then raise exception 'USUARIO_INVALIDO' using errcode='42501'; end if;
  select * into v_p from public.pedidos_personalizados_pedidos where id=p_pedido_id for update;
  if not found then raise exception 'PEDIDO_NAO_ENCONTRADO' using errcode='P0002'; end if;
  if v_p.version<>p_expected_version then raise exception 'CONFLITO_VERSAO' using errcode='P0003'; end if;
  select chave into v_f from public.pedidos_personalizados_fornecedores where id=v_p.fornecedor_id;
  if not ((v_p.status='RASCUNHO' and p_status_destino in ('VENDA FECHADA','CANCELADO'))
    or (v_f='lebebe_exclusive' and ((v_p.status='VENDA FECHADA' and p_status_destino in (U&'EM PRODU\00C7\00C3O','CANCELADO')) or (v_p.status=U&'EM PRODU\00C7\00C3O' and p_status_destino in ('RECEBIDO','CANCELADO'))))
    or (v_f='moriah_tapetes' and ((v_p.status='VENDA FECHADA' and p_status_destino in ('AGUARDANDO LAYOUT','CANCELADO')) or (v_p.status='AGUARDANDO LAYOUT' and p_status_destino in (U&'AGUARDANDO APROVA\00C7\00C3O DO CLIENTE','CANCELADO')) or (v_p.status=U&'AGUARDANDO APROVA\00C7\00C3O DO CLIENTE' and p_status_destino in (U&'EM PRODU\00C7\00C3O','AGUARDANDO LAYOUT','CANCELADO')) or (v_p.status=U&'EM PRODU\00C7\00C3O' and p_status_destino in ('RECEBIDO','CANCELADO'))))) then raise exception 'TRANSICAO_STATUS_INVALIDA' using errcode='P0001'; end if;
  v_lancamento:=case when (v_p.status='RASCUNHO' and p_status_destino='VENDA FECHADA') or (v_f='lebebe_exclusive' and v_p.status='VENDA FECHADA' and p_status_destino=U&'EM PRODU\00C7\00C3O') then coalesce(nullif(btrim(p_numero_lancamento),''),v_p.numero_lancamento) else v_p.numero_lancamento end;
  if p_numero_lancamento is not null and not ((v_p.status='RASCUNHO' and p_status_destino='VENDA FECHADA') or (v_f='lebebe_exclusive' and v_p.status='VENDA FECHADA' and p_status_destino=U&'EM PRODU\00C7\00C3O')) then raise exception 'NUMERO_LANCAMENTO_NAO_PERMITIDO' using errcode='22023'; end if;
  if v_f<>'lebebe_exclusive' and v_p.status='RASCUNHO' and p_status_destino='VENDA FECHADA' and (v_lancamento is null or v_lancamento !~ '^[0-9]{1,6}$') then raise exception 'NUMERO_LANCAMENTO_OBRIGATORIO' using errcode='23514'; end if;
  if v_f='lebebe_exclusive' and v_p.status='VENDA FECHADA' and p_status_destino=U&'EM PRODU\00C7\00C3O' then
    if v_lancamento is null or v_lancamento !~ '^[0-9]{1,6}$' then raise exception 'NUMERO_LANCAMENTO_OBRIGATORIO' using errcode='23514'; end if;
    select * into v_i from public.pedidos_personalizados_lebebe_exclusive_sgi where pedido_id=p_pedido_id for update;
    if not found or v_i.status_integracao<>'CONCLUIDO' or v_i.produto_id_sgi is null then raise exception 'PRODUTO_SGI_OBRIGATORIO' using errcode='23514'; end if;
    if v_i.lancamento_aplicado_em is null and v_i.status_renomeacao not in ('PENDENTE','PROCESSANDO') then
      update public.pedidos_personalizados_lebebe_exclusive_sgi set numero_lancamento_snapshot=v_lancamento,
        nome_produto_sgi='LEBEBE EXCLUSIVE ('||unidade_snapshot||' '||v_lancamento||' '||cliente_snapshot||')',status_renomeacao='PENDENTE',operacao_pendente='RENOMEAR_PRODUTO',solicitado_em=now(),claim_token=null,claim_expira_em=null
      where pedido_id=p_pedido_id;
    end if;
  end if;
  if v_f='moriah_tapetes' and p_status_destino in (U&'AGUARDANDO APROVA\00C7\00C3O DO CLIENTE',U&'EM PRODU\00C7\00C3O') and not exists(select 1 from public.pedidos_personalizados_moriah_tapetes t join public.pedidos_personalizados_anexos a on a.tapete_id=t.id where t.pedido_id=p_pedido_id) then raise exception 'ANEXO_LAYOUT_OBRIGATORIO' using errcode='23514'; end if;
  v_numero_pedido_compra:=coalesce(p_numero_pedido_compra,v_p.numero_pedido_compra); v_data_pedido_fornecedor:=coalesce(p_data_pedido_fornecedor,v_p.data_pedido_fornecedor); v_comprador:=coalesce(nullif(btrim(p_comprador),''),v_p.comprador); v_data_entrega:=case when p_status_destino=U&'EM PRODU\00C7\00C3O' then coalesce(p_data_entrega,v_p.data_entrega) else v_p.data_entrega end; v_data_recebimento:=case when p_status_destino='RECEBIDO' then p_data_entrega end; v_justificativa:=nullif(btrim(p_justificativa),'');
  v_preenche_dados_compra:=(v_f='moriah_tapetes' and v_p.status='VENDA FECHADA' and p_status_destino='AGUARDANDO LAYOUT') or (v_f='lebebe_exclusive' and v_p.status='VENDA FECHADA' and p_status_destino=U&'EM PRODU\00C7\00C3O');
  if v_preenche_dados_compra and (v_numero_pedido_compra is null or v_numero_pedido_compra !~ '^[0-9]{1,5}$' or v_data_pedido_fornecedor is null or v_comprador is null or char_length(btrim(v_comprador)) not between 2 and 40) then raise exception 'CAMPOS_PRODUCAO_OBRIGATORIOS' using errcode='23514'; end if;
  if p_status_destino=U&'EM PRODU\00C7\00C3O' and v_data_entrega is null then raise exception 'DATA_ENTREGA_OBRIGATORIA' using errcode='23514'; end if;
  if p_status_destino='RECEBIDO' and v_data_recebimento is null then raise exception 'DATA_RECEBIMENTO_OBRIGATORIA' using errcode='23514'; end if;
  if p_status_destino='CANCELADO' and (v_justificativa is null or char_length(v_justificativa)>500) then raise exception 'JUSTIFICATIVA_CANCELAMENTO_OBRIGATORIA' using errcode='23514'; end if;
  if p_status_destino<>'CANCELADO' and v_justificativa is not null then raise exception 'JUSTIFICATIVA_NAO_PERMITIDO' using errcode='22023'; end if;
  update public.pedidos_personalizados_pedidos as pedido set status=p_status_destino,
    numero_lancamento=case when (v_p.status='RASCUNHO' and p_status_destino='VENDA FECHADA') or (v_f='lebebe_exclusive' and p_status_destino=U&'EM PRODU\00C7\00C3O') then v_lancamento else numero_lancamento end,
    numero_pedido_compra=case when v_preenche_dados_compra then v_numero_pedido_compra else numero_pedido_compra end,
    data_pedido_fornecedor=case when v_preenche_dados_compra then v_data_pedido_fornecedor else data_pedido_fornecedor end,
    comprador=case when v_preenche_dados_compra then v_comprador else comprador end,
    data_entrega=case when p_status_destino=U&'EM PRODU\00C7\00C3O' then v_data_entrega else data_entrega end,
    version=v_p.version+1,updated_by=p_usuario_id where id=p_pedido_id returning pedido.version into v_version;
  insert into public.pedidos_personalizados_status_historico(id,pedido_id,status_anterior,status_novo,usuario_id,unidade_id,version_anterior,version_nova,justificativa,data_recebimento)
  values(v_evento,p_pedido_id,v_p.status,p_status_destino,p_usuario_id,v_p.unidade_id,v_p.version,v_version,case when p_status_destino='CANCELADO' then nullif(btrim(p_justificativa),'') end,case when p_status_destino='RECEBIDO' then p_data_entrega end);
  return query select v_evento,p_status_destino,v_version;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_superadmin_ativo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    superadmin_count INTEGER;
BEGIN
    -- Conta superadmins ativos após a operação
    IF TG_OP = 'DELETE' THEN
        SELECT COUNT(*) INTO superadmin_count
        FROM usuarios_permitidos
        WHERE role = 'superadmin' AND ativo = true AND id != OLD.id;
        
        IF superadmin_count = 0 THEN
            RAISE EXCEPTION 'Não é permitido remover o último superadmin ativo';
        END IF;
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        -- Se está tentando desativar ou mudar role de um superadmin
        IF OLD.role = 'superadmin' AND OLD.ativo = true THEN
            IF NEW.ativo = false OR NEW.role != 'superadmin' THEN
                SELECT COUNT(*) INTO superadmin_count
                FROM usuarios_permitidos
                WHERE role = 'superadmin' AND ativo = true AND id != OLD.id;
                
                IF superadmin_count = 0 THEN
                    RAISE EXCEPTION 'Não é permitido desativar ou alterar o último superadmin ativo';
                END IF;
            END IF;
        END IF;
        
        -- Proteger superadmins iniciais
        IF OLD.email IN ('lucas@lebebe.com.br', 'robyson@lebebe.com.br') THEN
            IF NEW.ativo = false THEN
                RAISE EXCEPTION 'Não é permitido desativar os superadmins iniciais';
            END IF;
        END IF;
        
        RETURN NEW;
    END IF;
    
    RETURN NEW;
END;
$function$
